import{_ as t,C as o,o as i,c as n,a2 as r,E as s}from"./chunks/framework.CBxkvBm_.js";const b=JSON.parse('{"title":"Tarjan Block Lower Triangular (BLT) Transformation","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/blt.md","filePath":"algorithms/blt.md"}'),l={name:"algorithms/blt.md"};function c(m,e,p,d,g,h){const a=o("MermaidBlock");return i(),n("div",null,[e[0]||(e[0]=r('<h1 id="tarjan-block-lower-triangular-blt-transformation" tabindex="-1">Tarjan Block Lower Triangular (BLT) Transformation <a class="header-anchor" href="#tarjan-block-lower-triangular-blt-transformation" aria-label="Permalink to &quot;Tarjan Block Lower Triangular (BLT) Transformation&quot;">​</a></h1><p><strong>Implementation</strong>: <code>BltEngine</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/structural/blt.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/structural/blt.ts</code></a></p><hr><h2 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h2><ul><li><strong>Tarjan, R. E. (1972)</strong>. <em>&quot;Depth-first search and linear graph algorithms.&quot;</em><br><strong>SIAM Journal on Computing</strong>, 1(2), pp. 146–160.<br> DOI: <a href="https://doi.org/10.1137/0201010" target="_blank" rel="noreferrer">10.1137/0201010</a> (Strongly Connected Components)</li><li><strong>Hopcroft, J. E., &amp; Karp, R. M. (1973)</strong>. <em>&quot;An $n^{5/2}$ algorithm for maximum matchings in bipartite graphs.&quot;</em><br><strong>SIAM Journal on Computing</strong>, 2(4), pp. 225–231.<br> DOI: <a href="https://doi.org/10.1137/0202019" target="_blank" rel="noreferrer">10.1137/0202019</a> (Bipartite Matching)</li><li><strong>Dulmage, A. L., &amp; Mendelsohn, N. S. (1958)</strong>. <em>&quot;Coverings of bipartite graphs.&quot;</em><br><strong>Canadian Journal of Mathematics</strong>, 10, pp. 517–534.<br> DOI: <a href="https://doi.org/10.4153/CJM-1958-052-0" target="_blank" rel="noreferrer">10.4153/CJM-1958-052-0</a></li><li><strong>Cellier, F. E., &amp; Kofman, E. (2006)</strong>. <em>Continuous System Simulation</em>.<br><strong>Springer</strong>. ISBN: <a href="https://link.springer.com/book/10.1007/0-387-30260-3" target="_blank" rel="noreferrer">978-0-387-26102-7</a></li></ul><hr><h2 id="modelscript-architectural-rationale" tabindex="-1">ModelScript Architectural Rationale <a class="header-anchor" href="#modelscript-architectural-rationale" aria-label="Permalink to &quot;ModelScript Architectural Rationale&quot;">​</a></h2><p>Flattening industrial physical systems results in coupled systems comprising thousands of equations and variables. Solving a monolithic non-linear algebraic system of size $N$ using general Newton-Raphson methods incurs a cubic computational penalty per step:</p><p>$$\\mathcal{O}(N^3)$$</p><p>The Block Lower Triangular (BLT) transformation permutes the equation and variable ordering so that the incidence matrix assumes a lower triangular block diagonal structure:</p><p>$$ \\begin{pmatrix} A_{11} &amp; 0 &amp; \\cdots &amp; 0 \\ A_{21} &amp; A_{22} &amp; \\cdots &amp; 0 \\ \\vdots &amp; \\vdots &amp; \\ddots &amp; \\vdots \\ A_{m1} &amp; A_{m2} &amp; \\cdots &amp; A_{mm} \\end{pmatrix} \\begin{pmatrix} x_1 \\ x_2 \\ \\vdots \\ x_m \\end{pmatrix} = \\begin{pmatrix} b_1 \\ b_2 \\ \\vdots \\ b_m \\end{pmatrix} $$</p><p>Most blocks $A_{ii}$ are trivial $1 \\times 1$ scalar explicit assignments ($x_i = f(\\dots)$), while only non-linear algebraic loops become coupled sub-blocks of size $k \\ll N$.</p><hr><h2 id="modelscript-modifications-wasm-architecture" tabindex="-1">ModelScript Modifications &amp; WASM Architecture <a class="header-anchor" href="#modelscript-modifications-wasm-architecture" aria-label="Permalink to &quot;ModelScript Modifications &amp; WASM Architecture&quot;">​</a></h2><ol><li><strong>Compressed Sparse Row (CSR) in Linear Memory</strong>: Bipartite incidence graphs are stored in contiguous <code>ChunkedInt32Array</code> buffers (<code>eqDepPtrs</code>, <code>eqDepVars</code>).</li><li><strong>Zero-Allocation Tarjan Traversal</strong>: Low-link values, depth indices, and traversal stacks operate strictly on 32-bit integer offsets in WebAssembly memory without object references.</li><li><strong>Integrated Maximum Matching</strong>: Hopcroft-Karp augmenting path search provides consistent equation-to-variable assignments for directed SCC analysis.</li><li><strong>Direct Bridge to Tearing</strong>: SCC blocks with dimension $&gt; 1$ pass directly to the in-WASM <code>TornBlock</code> engine.</li></ol><hr><h2 id="algorithm-description-pipeline-flow" tabindex="-1">Algorithm Description &amp; Pipeline Flow <a class="header-anchor" href="#algorithm-description-pipeline-flow" aria-label="Permalink to &quot;Algorithm Description &amp; Pipeline Flow&quot;">​</a></h2>',17)),s(a,{code:"flowchart%20TD%0A%20%20%20%20DAE%5B%22Flattened%20%26%20Index-Reduced%20DAE%22%5D%20--%3E%20CSR%5B%221.%20Build%20CSR%20Incidence%20Graph%3Cbr%2F%3EeqDepPtrs%20%26%20eqDepVars%22%5D%0A%20%20%20%20CSR%20--%3E%20MATCH%5B%222.%20Maximum%20Bipartite%20Matching%3Cbr%2F%3E(Hopcroft-Karp%20%2F%20Augmenting%20Paths)%22%5D%0A%20%20%20%20MATCH%20--%3E%20DIRECT%5B%223.%20Direct%20the%20Dependency%20Graph%3Cbr%2F%3EDirect%20edge%20from%20Var%20to%20Eq%20if%20matched%2C%20else%20Eq%20to%20Var%22%5D%0A%20%20%20%20DIRECT%20--%3E%20TARJAN%5B%224.%20Tarjan's%20SCC%20Algorithm%3Cbr%2F%3ECompute%20index%20%26%20lowlink%20values%20on%20stack%22%5D%0A%20%20%20%20TARJAN%20--%3E%20PARTITION%5B%225.%20Topological%20BLT%20Ordering%3Cbr%2F%3EOrder%20SCC%20blocks%20topologically%22%5D%0A%20%20%20%20PARTITION%20--%3E%20DISPATCH%7B%22Block%20Size%3F%22%7D%0A%20%20%20%20DISPATCH%20--%3E%7CSize%20%3D%201%7C%20EXPLICIT%5B%22Explicit%20Scalar%20Assignment%3Cbr%2F%3EDirect%20code%20execution%22%5D%0A%20%20%20%20DISPATCH%20--%3E%7CSize%20%3E%201%7C%20TEAR%5B%22Algebraic%20Loop%20Core%3Cbr%2F%3EForward%20to%20Cellier-Elmqvist%20Tearing%22%5D%0A"}),e[1]||(e[1]=r('<hr><h2 id="upstream-downstream-pipeline-connections" tabindex="-1">Upstream &amp; Downstream Pipeline Connections <a class="header-anchor" href="#upstream-downstream-pipeline-connections" aria-label="Permalink to &quot;Upstream &amp; Downstream Pipeline Connections&quot;">​</a></h2><ul><li><strong>Upstream Inputs</strong>: <ul><li>Ingests index-reduced DAE systems from <a href="./pantelides.html"><code>PantelidesEngine</code></a>.</li></ul></li><li><strong>Downstream Consumers</strong>: <ul><li>Trivial $1 \\times 1$ blocks are lowered directly into sequence evaluation bytecode.</li><li>Coupled blocks (size $&gt; 1$) are sent to <a href="./tearing.html"><code>TornBlock</code></a> for algebraic loop tearing.</li><li>Drives step evaluations in <a href="./solvers-ode-dae.html"><code>SUNDIALS CVODE/IDA</code></a> and <a href="./solvers-ode-dae.html"><code>Tsit5</code></a>.</li></ul></li></ul>',3))])}const f=t(l,[["render",c]]);export{b as __pageData,f as default};
